import{_ as l,o as i,c as t,a5 as a}from"./chunks/framework.BPFk9-tb.js";const h=JSON.parse('{"title":"写作课作业-101","description":"","frontmatter":{"date":"2020-11-03T00:04:30","title":"写作课作业-101","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/101.md","filePath":"posts/homework/101.md"}'),o={name:"posts/homework/101.md"};function r(p,e,s,n,_,c){return i(),t("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《一年顶十年》之《写作 如何成为一名很圈粉的写作者？》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>写作时“改运”级的武器。写作能让你想得更明白，大大提高你的思考质量。经常写作会更容易捕捉到有价值的信息。公开写作，能帮你链接到同频的人。写作时打造个人品牌的神器。</li><li>如何打好写作基础：要多读优秀作品；要多写，多改；死磕阅读法。</li><li>刚开始写时，可以从方便写，且对读者有启发的内容开始。</li><li>训练起标题的能力：经常扫标题，多起几个标题。</li><li>写不出来东西的时候，不要干坐着冥思苦想，你应该去“进货”——从书里“进货”， 从牛人那里“进货”， 从现实生活中“进货”。读好书、见牛人、多观察，多提问、多分析、多总结。</li><li>遇到有人说你文章写得不好，甚至骂你，你就把这当成一种鞭策。你出了继续写，好好写，让自己写得更好，别无选择。</li><li>写作不是自说自话，而是跟人交流、分享。我们写的文章，要让人愿意看、看得懂、看了之后有说启发。</li><li>简洁流畅、有说服力比文采更重要，而自己是一个有结果的人更重要——做得好，并写得好。</li><li>一个合格的写作者，应该有自己坚信的原则、理念。梳理自己的原则和理念时先做加法后做减法。</li><li>开始写吧，不管你的基础怎么样。不仅要多写，还要努力写出值得传播的代表作。</li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>写作时常被自己认为是一个苦力活，一个原因是自己的思考不够，而思考不够的原因，是读得不够。</p><p>像培养自己的锻炼的微习惯一样，每天读十几页书，每天写几十个字。</p><p>开始写，真没自己想的那么难，但也不简单。可以慢，但不要半途而废。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',14)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
